package cn.zhigeng.app;

import android.app.*;import android.os.*;import android.net.Uri;import android.graphics.Color;import android.view.*;import android.widget.*;import android.text.Html;
import org.w3c.dom.*;import javax.xml.parsers.DocumentBuilderFactory;
import java.io.*;import java.nio.charset.*;import java.util.*;import java.util.zip.*;

/** Local TXT and EPUB text reader; URI stays on device, no upload. */
public class ReaderActivity extends Activity {
    private ScrollView scroll;private TextView content,progress;private android.content.SharedPreferences prefs;private String id;private float font=19;private boolean ready=false;
    @Override public void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences("reader",MODE_PRIVATE);id=getIntent().getStringExtra("uri");font=prefs.getFloat("font",19);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(Color.rgb(248,247,238));setContentView(root);LinearLayout bar=new LinearLayout(this);bar.setPadding(12,12,12,8);Button back=new Button(this);back.setText("返回");back.setOnClickListener(v->finish());bar.addView(back);TextView title=new TextView(this);title.setText(getIntent().getStringExtra("title"));title.setTextSize(16);title.setTextColor(0xff23342b);title.setMaxLines(1);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button smaller=new Button(this);smaller.setText("A−");Button larger=new Button(this);larger.setText("A+");bar.addView(smaller,new LinearLayout.LayoutParams(68,55));bar.addView(larger,new LinearLayout.LayoutParams(68,55));root.addView(bar);
        scroll=new ScrollView(this);content=new TextView(this);content.setPadding(26,20,26,40);content.setTextSize(font);content.setTextColor(0xff293b30);content.setLineSpacing(10,1.25f);content.setTextIsSelectable(true);content.setText("正在打开本地文件…");scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bottom=new LinearLayout(this);progress=new TextView(this);progress.setPadding(20,10,10,10);bottom.addView(progress,new LinearLayout.LayoutParams(0,-2,1));Button mark=new Button(this);mark.setText("记书签");bottom.addView(mark);Button jump=new Button(this);jump.setText("回书签");bottom.addView(jump);root.addView(bottom);
        smaller.setOnClickListener(v->{font=Math.max(13,font-1);content.setTextSize(font);});larger.setOnClickListener(v->{font=Math.min(32,font+1);content.setTextSize(font);});mark.setOnClickListener(v->{prefs.edit().putInt(id+":bookmark",scroll.getScrollY()).apply();Toast.makeText(this,"书签已保存",0).show();});jump.setOnClickListener(v->scroll.smoothScrollTo(0,prefs.getInt(id+":bookmark",0)));
        scroll.setOnScrollChangeListener((v,x,y,ox,oy)->{int max=Math.max(1,content.getHeight()-scroll.getHeight());progress.setText("已读 "+Math.min(100,Math.round(y*100f/max))+"%");});
        new Thread(()->{String value;try(InputStream in=getContentResolver().openInputStream(Uri.parse(id))){if(in==null)throw new Exception("无法访问文件");value="epub".equals(getIntent().getStringExtra("format"))?epub(in):text(bytes(in,16_000_000));}catch(Exception e){value="无法打开："+e.getMessage()+"\n可重新导入文件后再试。";}String result=value;runOnUiThread(()->{if(isFinishing())return;content.setText(result);ready=true;scroll.post(()->scroll.scrollTo(0,prefs.getInt(id+":position",0)));});},"local-reader").start();
    }
    private static byte[] bytes(InputStream in,int max)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new Exception("图书过大，请使用专业阅读器打开");out.write(b,0,n);}return out.toByteArray();}
    private static String text(byte[] b){try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(b)).toString().replace("\uFEFF","");}catch(Exception e){return new String(b,Charset.forName("GB18030"));}}
    private static Document xml(byte[] data)throws Exception{DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);f.setFeature("http://xml.org/sax/features/external-general-entities",false);f.setFeature("http://xml.org/sax/features/external-parameter-entities",false);return f.newDocumentBuilder().parse(new ByteArrayInputStream(data));}
    private static String epub(InputStream input)throws Exception{
        Map<String,byte[]> entries=new LinkedHashMap<>();int total=0,count=0;
        try(ZipInputStream zip=new ZipInputStream(input)){ZipEntry entry;while((entry=zip.getNextEntry())!=null){if(++count>5000)throw new Exception("EPUB 文件条目过多");String name=entry.getName();if(entry.isDirectory()||!(name.endsWith(".xml")||name.endsWith(".opf")||name.endsWith(".html")||name.endsWith(".xhtml")||name.endsWith(".htm")))continue;byte[] b=bytes(zip,4_000_000);total+=b.length;if(total>24_000_000)throw new Exception("EPUB 文本过大");entries.put(name,b);}}
        String opf="";byte[] container=entries.get("META-INF/container.xml");if(container!=null){NodeList paths=xml(container).getElementsByTagNameNS("*","rootfile");if(paths.getLength()>0)opf=((Element)paths.item(0)).getAttribute("full-path");}
        List<String> readingOrder=new ArrayList<>();if(entries.containsKey(opf)){Document packageDoc=xml(entries.get(opf));Map<String,String> manifest=new HashMap<>();String base=opf.contains("/")?opf.substring(0,opf.lastIndexOf('/')+1):"";NodeList items=packageDoc.getElementsByTagNameNS("*","item");for(int i=0;i<items.getLength();i++){Element e=(Element)items.item(i);manifest.put(e.getAttribute("id"),base+Uri.decode(e.getAttribute("href").split("#")[0]));}NodeList refs=packageDoc.getElementsByTagNameNS("*","itemref");for(int i=0;i<refs.getLength();i++){String path=manifest.get(((Element)refs.item(i)).getAttribute("idref"));if(path!=null)readingOrder.add(path);}}
        if(readingOrder.isEmpty())for(String name:entries.keySet())if(name.matches(".*\\.(xhtml|html|htm)$"))readingOrder.add(name);
        StringBuilder result=new StringBuilder();for(String name:readingOrder){byte[] data=entries.get(name);if(data==null)continue;String html=new String(data,StandardCharsets.UTF_8).replaceAll("(?is)<(script|style)[^>]*>.*?</\\1>","");result.append(Html.fromHtml(html,Html.FROM_HTML_MODE_LEGACY)).append("\n\n");if(result.length()>6_000_000)throw new Exception("EPUB 文本过大");}if(result.length()==0)throw new Exception("未找到可读取的 EPUB 正文，文件可能加密");return result.toString();
    }
    @Override protected void onPause(){super.onPause();if(ready)prefs.edit().putInt(id+":position",scroll.getScrollY()).putFloat("font",font).apply();}
}
